`timescale 1ns/1ps
module tb;
    reg clk = 0;
    integer comparisons = 0;
    integer mismatches = 0;
    reg reset=0,enable=0; wire [3:0] state; reg [3:0] expected; integer i;
    TopModule dut(.clk(clk),.reset(reset),.enable(enable),.state(state));
    task tick;
        begin #1; clk = 1; #1; clk = 0; #1; end
    endtask
    task check;
        input condition;
        begin
            if (!condition) mismatches = mismatches + 1;
            $display("CHECK idx=%0d match=%0d", comparisons, condition);
            comparisons = comparisons + 1;
        end
    endtask
    initial begin
        reset=1;tick();reset=0;expected=4'b0001;check(state===expected);enable=1;
        for(i=0;i<12;i=i+1)begin expected={expected[2:0],expected[3]^expected[2]};tick();check(state===expected);end
        $display("SUMMARY comparisons=%0d mismatches=%0d", comparisons, mismatches);
        $finish;
    end
endmodule

