tasks.adjacent:
module TopModule(input clk,input reset,input push,input pop,input [7:0] data_in,output full,output empty,output [7:0] top,output reg [1:0] count);
reg [7:0] m0,m1; assign full=(count==2); assign empty=(count==0); assign top=(count==0)?0:(count==1)?m0:m1;
always @(posedge clk) begin if(reset) begin count<=0;m0<=0;m1<=0;end else if(push&&!full) begin m0<=data_in;count<=count+1;end else if(pop&&!empty) count<=count-1;end endmodule

