module TopModule(
    input clk,
    input reset,
    input enable,
    output reg [2:0] phase
);
    always @(posedge clk) begin
        if (reset)
            phase <= 3'd0;
        else if (enable)
            phase <= (phase == 3'd3) ? 3'd0 : phase + 3'd1;
    end
endmodule

