`timescale 1ns/1ps
module tb;
    reg clk = 0;
    reg reset = 0;
    reg enable = 0;
    wire [2:0] phase;
    integer vector_index;
    integer step;
    integer expected;
    integer comparisons = 0;
    integer mismatches = 0;
    TopModule dut(.clk(clk), .reset(reset), .enable(enable), .phase(phase));

    task reset_dut;
        begin
            enable = 0; reset = 1;
            #1; clk = 1; #1; clk = 0; #1;
            reset = 0; expected = 0;
        end
    endtask

    task drive_edge;
        input integer selected_enable;
        begin
            enable = selected_enable;
            if (enable) expected = (expected == 4) ? 0 : expected + 1;
            #1; clk = 1; #1;
            if (phase !== expected[2:0]) mismatches = mismatches + 1;
            $display("CHECK idx=%0d actual=%0h expected=%0h match=%0d", comparisons, phase, expected[2:0], phase === expected[2:0]);
            comparisons = comparisons + 1;
            clk = 0; #1;
        end
    endtask

    initial begin
        for (vector_index = 0; vector_index < 64; vector_index = vector_index + 1) begin
            reset_dut();
