`timescale 1ns/1ps
module tb;
    reg clk = 0;
    reg reset = 0;
    reg inc = 0;
    reg dec = 0;
    wire [2:0] count;
    integer vector_index;
    integer step;
    integer action;
    integer expected;
    integer comparisons = 0;
    integer mismatches = 0;
    TopModule dut(.clk(clk), .reset(reset), .inc(inc), .dec(dec), .count(count));

    task reset_dut;
        begin
            inc = 0; dec = 0; reset = 1;
            #1; clk = 1; #1; clk = 0; #1;
            reset = 0; expected = 3;
        end
    endtask

    task drive_edge;
        input integer selected_action;
        begin
            inc = selected_action & 1;
            dec = (selected_action >> 1) & 1;
            if (inc && !dec)
                expected = (expected == 6) ? expected : expected + 1;
            else if (dec && !inc)
                expected = (expected == 1) ? expected : expected - 1;
            #1; clk = 1; #1;
            if (count !== expected[2:0]) mismatches = mismatches + 1;
            $display("CHECK idx=%0d actual=%0h expected=%0h match=%0d", comparisons, count, expected[2:0], count === expected[2:0]);
            comparisons = comparisons + 1;
            clk = 0; #1;
        end
    endtask

    initial begin
        for (vector_index = 0; vector_index < 256; vector_index = vector_index + 1) begin
            reset_dut();
            for (step = 0; step < 4; step = step + 1) begin
                action = (vector_index >> (step * 2)) & 3;
                drive_edge(action);
            end
        end
        $display("SUMMARY comparisons=%0d mismatches=%0d", comparisons, mismatches);
        $finish;
    end
endmodule

