`timescale 1ns/1ps
module tb;
    integer comparisons = 0;
    integer mismatches = 0;
    reg[4:0]a;wire[4:0]y;integer i;
    TopModule dut(.a(a),.y(y));
    task check;
        input condition;
        begin
            if (!condition) mismatches = mismatches + 1;
            $display("CHECK idx=%0d match=%0d", comparisons, condition);
            comparisons = comparisons + 1;
        end
    endtask
    initial begin
        for(i=0;i<32;i=i+1)begin a=i;#1;check(y===a);end
        $display("SUMMARY comparisons=%0d mismatches=%0d", comparisons, mismatches);
        $finish;
    end
endmodule

